SELECT series, groupArray((t, v)) AS points,
       groupArray((t, ex.1, ex.2, ex.3)) AS exemplars
FROM (SELECT series, t, v, ex FROM (SELECT toString('') AS series, (intDiv(start_ns - 1, 60000000000) + 1) * 60000 AS t, toFloat64(quantilesTDigest(0.9)(duration_ns)[1]) AS v, argMax((lower(hex(trace_id)), lower(hex(span_id)), duration_ns), (duration_ns, span_id)) AS ex FROM tqd_cat.spans WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND (multiIf(dynamicType(attrs.`a`) != 'None', (coalesce(attrs.`a`.:Int64 = 1, false) OR coalesce(attrs.`a`.:Float64 = 1, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`a`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`a`.:Int64 = 1, false) OR coalesce(attrs.`a`.:Float64 = 1, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`a`), arrayExists(x -> x = 1, events.attrs.`a`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`a`), arrayExists(x -> x = 1, links.attrs.`a`.:Int64), multiIf(dynamicType(scope_attrs.`a`) != 'None', (coalesce(scope_attrs.`a`.:Int64 = 1, false) OR coalesce(scope_attrs.`a`.:Float64 = 1, false)), false)))))) GROUP BY series, t) ORDER BY series, t)
GROUP BY series ORDER BY series
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001, output_format_json_quote_64bit_integers = 0
FORMAT JSONCompact
